/**
 * @module
 * Rate Limit Middleware for Hono.
 */

import type { Context } from '../../context'
import type { MiddlewareHandler } from '../../types'

type KeyGenerator = (c: Context) => string
type SkipFunction = (c: Context) => boolean
type RateLimitHandler = (c: Context) => Response | Promise<Response>

export interface RateLimitOptions {
  limit?: number
  windowMs?: number
  keyGenerator?: KeyGenerator
  skip?: SkipFunction
  handler?: RateLimitHandler
}

interface RateLimitRecord {
  count: number
  resetAt: number
}

const defaultKeyGenerator: KeyGenerator = (c) => {
  const forwardedFor = c.req.header('x-forwarded-for')
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim()
    if (first) {
      return first
    }
  }
  return c.req.header('x-real-ip') || 'global'
}

/**
 * Rate Limit Middleware for Hono.
 *
 * @param {RateLimitOptions} [options] - The options for the rate limit middleware.
 * @param {number} [options.limit=100] - The maximum number of requests allowed per window.
 * @param {number} [options.windowMs=60000] - The time window in milliseconds.
 * @param {KeyGenerator} [options.keyGenerator] - A function to generate a unique key per client. Defaults to the remote IP.
 * @param {SkipFunction} [options.skip] - A function to skip rate limiting for certain requests.
 * @param {RateLimitHandler} [options.handler] - A custom handler returning the 429 response.
 * @returns {MiddlewareHandler} The middleware handler function.
 *
 * @example
 * ```ts
 * const app = new Hono()
 *
 * app.use(rateLimit({ limit: 10, windowMs: 60_000 }))
 * app.get('/', (c) => c.text('Hello!'))
 * ```
 */
export const rateLimit = (options: RateLimitOptions = {}): MiddlewareHandler => {
  const limit = options.limit ?? 100
  const windowMs = options.windowMs ?? 60000
  const keyGenerator = options.keyGenerator ?? defaultKeyGenerator
  const skip = options.skip
  const handler =
    options.handler ??
    ((c: Context) =>
      new Response(JSON.stringify({ error: 'Too Many Requests' }), {
        status: 429,
        headers: { 'content-type': 'application/json' },
      }))

  const store = new Map<string, RateLimitRecord>()

  return async function rateLimit(c, next) {
    if (skip && skip(c)) {
      return next()
    }

    const key = keyGenerator(c)
    const now = Date.now()
    let record = store.get(key)

    if (!record || record.resetAt <= now) {
      record = { count: 0, resetAt: now + windowMs }
      store.set(key, record)
    }

    record.count++

    const remaining = Math.max(0, limit - record.count)
    const resetSeconds = Math.ceil((record.resetAt - now) / 1000)

    c.header('X-RateLimit-Limit', String(limit))
    c.header('X-RateLimit-Remaining', String(remaining))
    c.header('X-RateLimit-Reset', String(Math.ceil(record.resetAt / 1000)))

    if (record.count > limit) {
      c.header('Retry-After', String(resetSeconds))
      return handler(c)
    }

    await next()
  }
}

