import { Hono } from '../../hono'
import { rateLimit } from '.'

describe('Rate Limit Middleware', () => {
  afterEach(() => {
    vi.useRealTimers()
  })

  it('Should allow requests under the limit', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 3, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    for (let i = 0; i < 3; i++) {
      const res = await app.request('http://localhost/', {
        headers: { 'x-forwarded-for': '1.2.3.4' },
      })
      expect(res.status).toBe(200)
      expect(await res.text()).toBe('ok')
    }
  })

  it('Should return 429 when the limit is exceeded', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 2, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    await app.request('http://localhost/', { headers: { 'x-forwarded-for': '1.2.3.4' } })
    await app.request('http://localhost/', { headers: { 'x-forwarded-for': '1.2.3.4' } })
    const res = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })

    expect(res.status).toBe(429)
    expect(res.headers.get('Content-Type')).toMatch('application/json')
    expect(await res.json()).toEqual({ error: 'Too Many Requests' })
    expect(res.headers.get('Retry-After')).not.toBeNull()
  })

  it('Should set rate-limit headers on responses', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 5, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    const res = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    expect(res.status).toBe(200)
    expect(res.headers.get('X-RateLimit-Limit')).toBe('5')
    expect(res.headers.get('X-RateLimit-Remaining')).toBe('4')
    expect(res.headers.get('X-RateLimit-Reset')).not.toBeNull()
  })

  it('Should track different IPs independently', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 1, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    const res1 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    const res2 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '5.6.7.8' },
    })

    expect(res1.status).toBe(200)
    expect(res2.status).toBe(200)
  })

  it('Should use x-forwarded-for first entry as the key', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 1, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    const res1 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4, 9.9.9.9' },
    })
    const res2 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4, 8.8.8.8' },
    })

    expect(res1.status).toBe(200)
    expect(res2.status).toBe(429)
  })

  it('Should fall back to x-real-ip when x-forwarded-for is absent', async () => {
    const app = new Hono()
    app.use('*', rateLimit({ limit: 1, windowMs: 60_000 }))
    app.get('/', (c) => c.text('ok'))

    const res1 = await app.request('http://localhost/', {
      headers: { 'x-real-ip': '10.0.0.1' },
    })
    const res2 = await app.request('http://localhost/', {
      headers: { 'x-real-ip': '10.0.0.1' },
    })

    expect(res1.status).toBe(200)
    expect(res2.status).toBe(429)
  })

  it('Should use a custom keyGenerator', async () => {
    const app = new Hono()
    app.use(
      '*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        keyGenerator: (c) => c.req.header('x-user-id') ?? 'anon',
      })
    )
    app.get('/', (c) => c.text('ok'))

    const res1 = await app.request('http://localhost/', { headers: { 'x-user-id': 'a' } })
    const res2 = await app.request('http://localhost/', { headers: { 'x-user-id': 'b' } })
    const res3 = await app.request('http://localhost/', { headers: { 'x-user-id': 'a' } })

    expect(res1.status).toBe(200)
    expect(res2.status).toBe(200)
    expect(res3.status).toBe(429)
  })

  it('Should bypass rate limiting when skip returns true', async () => {
    const app = new Hono()
    app.use(
      '*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        skip: (c) => c.req.header('x-admin') === '1',
      })
    )
    app.get('/', (c) => c.text('ok'))

    for (let i = 0; i < 5; i++) {
      const res = await app.request('http://localhost/', {
        headers: { 'x-forwarded-for': '1.2.3.4', 'x-admin': '1' },
      })
      expect(res.status).toBe(200)
    }
  })

  it('Should call custom handler on limit exceeded', async () => {
    const app = new Hono()
    app.use(
      '*',
      rateLimit({
        limit: 1,
        windowMs: 60_000,
        handler: (c) => c.text('slow down', 429),
      })
    )
    app.get('/', (c) => c.text('ok'))

    await app.request('http://localhost/', { headers: { 'x-forwarded-for': '1.2.3.4' } })
    const res = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })

    expect(res.status).toBe(429)
    expect(await res.text()).toBe('slow down')
  })

  it('Should reset counts after the window expires', async () => {
    vi.useFakeTimers().setSystemTime(new Date(0))

    const app = new Hono()
    app.use('*', rateLimit({ limit: 1, windowMs: 1000 }))
    app.get('/', (c) => c.text('ok'))

    const res1 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    expect(res1.status).toBe(200)

    const res2 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    expect(res2.status).toBe(429)

    vi.setSystemTime(new Date(2000))

    const res3 = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    expect(res3.status).toBe(200)
  })

  it('Should use defaults when no options are provided', async () => {
    const app = new Hono()
    app.use('*', rateLimit())
    app.get('/', (c) => c.text('ok'))

    const res = await app.request('http://localhost/', {
      headers: { 'x-forwarded-for': '1.2.3.4' },
    })
    expect(res.status).toBe(200)
    expect(res.headers.get('X-RateLimit-Limit')).toBe('100')
    expect(res.headers.get('X-RateLimit-Remaining')).toBe('99')
  })
})

